/**
 * Generate matte for individual objects and materials using Cryptomatte render passes
 *
 * bpy.types.CompositorNodeCryptomatteV2
 */
export interface CompositorNodeCryptomatteV2 extends R.CompositorNode {
  /**
   * Where the Cryptomatte passes are loaded from Default: 'RENDER'.
   * - `RENDER`: Render (Use Cryptomatte passes from a render)
   * - `IMAGE`: Image (Use Cryptomatte passes from an image)
   */
  get source(): H.Ref<"RENDER" | "IMAGE">;
  set source(v: H.In<"RENDER" | "IMAGE">);
  /** Scene */
  get scene(): H.Ptr<R.Scene>;
  set scene(v: R.Scene | null);
  /** Image */
  get image(): H.Ptr<R.Image>;
  set image(v: R.Image | null);
  /** List of object and material crypto IDs to include in matte Default: "". */
  get matte_id(): H.Ref<string>;
  set matte_id(v: H.In<string>);
  /** Add object or material to matte, by picking a color from the Pick output Default: (1.0, 1.0, 1.0). */
  get add(): H.Remote<M.Color>;
  set add(v: H.In<M.Color | readonly number[]>);
  /** Remove object or material from matte, by picking a color from the Pick output Default: (1.0, 1.0, 1.0). */
  get remove(): H.Remote<M.Color>;
  set remove(v: H.In<M.Color | readonly number[]>);
  /**
   * What Cryptomatte layer is used Default: 'CryptoObject'.
   * - `CryptoObject`: Object (Use Object layer)
   * - `CryptoMaterial`: Material (Use Material layer)
   * - `CryptoAsset`: Asset (Use Asset layer)
   */
  get layer_name(): H.Ref<"CryptoObject" | "CryptoMaterial" | "CryptoAsset" | (string & {})>;
  set layer_name(v: H.In<"CryptoObject" | "CryptoMaterial" | "CryptoAsset" | (string & {})>);
  /** Mattes */
  readonly entries: H.Own<H.Coll<R.CryptomatteEntry>>;
  /** Number of images of a movie to use Range: 0 to 1048574. Default: 0. */
  get frame_duration(): H.Ref<number>;
  set frame_duration(v: H.In<number>);
  /** Global starting frame of the movie/sequence, assuming first picture has a #1 Range: -1048574 to 1048574. Default: 0. */
  get frame_start(): H.Ref<number>;
  set frame_start(v: H.In<number>);
  /** Offset the number of the frame to use in the animation Range: -1048574 to 1048574. Default: 0. */
  get frame_offset(): H.Ref<number>;
  set frame_offset(v: H.In<number>);
  /** Cycle the images in the movie Default: False. */
  get use_cyclic(): H.Ref<boolean>;
  set use_cyclic(v: H.In<boolean>);
  /** Always refresh image on frame changes Default: False. */
  get use_auto_refresh(): H.Ref<boolean>;
  set use_auto_refresh(v: H.In<boolean>);
  /**
   * Layer Default: 'PLACEHOLDER'.
   * - `PLACEHOLDER`: Placeholder
   */
  get layer(): H.Ref<string>;
  set layer(v: H.In<string>);
  /** True if this image has any named layer Default: False. */
  get has_layers(): H.Ref<boolean>;
  /**
   * View Default: 'ALL'.
   * - `ALL`: All
   */
  get view(): H.Ref<string>;
  set view(v: H.In<string>);
  /** True if this image has multiple views Default: False. */
  get has_views(): H.Ref<boolean>;
  /** Input socket template */
  input_template(index: H.In<number>): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Input socket template */
  input_template(kw: { index: H.In<number> }): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Output socket template */
  output_template(index: H.In<number>): H.Ptr<R.NodeInternalSocketTemplate>;
  /** Output socket template */
  output_template(kw: { index: H.In<number> }): H.Ptr<R.NodeInternalSocketTemplate>;
  readonly inputs: R.Node["inputs"] & {
    /** This node's inputs by name (any other name is a NodeSocket). */
    readonly $: {
      readonly "Image": H.Ptr<R.NodeSocketColor>;
    };
  };
  readonly outputs: R.Node["outputs"] & {
    /** This node's outputs by name (any other name is a NodeSocket). */
    readonly $: {
      readonly "Image": H.Ptr<R.NodeSocketColor>;
      readonly "Matte": H.Ptr<R.NodeSocketFloat>;
      readonly "Pick": H.Ptr<R.NodeSocketColor>;
    };
  };
}

