/** bpy.types.CyclesMaterialSettings */
export interface CyclesMaterialSettings extends R.PropertyGroup {
  /**
   * Sampling strategy for emissive surfaces Default: 'AUTO'.
   * - `NONE`: None (Do not use this surface as a light for sampling)
   * - `AUTO`: Auto (Automatically determine if the surface should be treated as a light for sampling, based on estimated emission intensity)
   * - `FRONT`: Front (Treat only front side of the surface as a light, usually for closed meshes whose interior is not visible)
   * - `BACK`: Back (Treat only back side of the surface as a light for sampling)
   * - `FRONT_BACK`: Front and Back (Treat surface as a light for sampling, emitting from both the front and back side)
   */
  get emission_sampling(): H.Ref<"NONE" | "AUTO" | "FRONT" | "BACK" | "FRONT_BACK">;
  set emission_sampling(v: H.In<"NONE" | "AUTO" | "FRONT" | "BACK" | "FRONT_BACK">);
  /** Apply corrections to solve shadow terminator artifacts caused by bump mapping Default: True. */
  get use_bump_map_correction(): H.Ref<boolean>;
  set use_bump_map_correction(v: H.In<boolean>);
  /**
   * Sampling method to use for volumes Default: 'MULTIPLE_IMPORTANCE'.
   * - `DISTANCE`: Distance (Use distance sampling, best for dense volumes with lights far away)
   * - `EQUIANGULAR`: Equiangular (Use equiangular sampling, best for volumes with low density with light inside or near the volume)
   * - `MULTIPLE_IMPORTANCE`: Multiple Importance (Combine distance and equi-angular sampling for volumes where neither method is ideal)
   */
  get volume_sampling(): H.Ref<"DISTANCE" | "EQUIANGULAR" | "MULTIPLE_IMPORTANCE">;
  set volume_sampling(v: H.In<"DISTANCE" | "EQUIANGULAR" | "MULTIPLE_IMPORTANCE">);
  /**
   * Interpolation method to use for smoke/fire volumes Default: 'LINEAR'.
   * - `LINEAR`: Linear (Good smoothness and speed)
   * - `CUBIC`: Cubic (Smoothed high quality interpolation, but slower)
   */
  get volume_interpolation(): H.Ref<"LINEAR" | "CUBIC">;
  set volume_interpolation(v: H.In<"LINEAR" | "CUBIC">);
  /** Scale the distance between volume shader samples when rendering the volume (lower values give more accurate and detailed results, but also increased render time) Range: 0.0010000000474974513 to 1000. Default: 1.0. */
  get volume_step_rate(): H.Ref<number>;
  set volume_step_rate(v: H.In<number>);
  register(): H.Ref<void>;
  unregister(): H.Ref<void>;
}

